D='/workspace/prico/www/i18n/'
for l,(a,b,c,d) in L.items():
    assert len(a)==len(K) and len(b)==len(SC) and len(c)==len(CD) and len(d)==len(CD), (l,len(a),len(b),len(c),len(d))
    pairs=list(zip(K,a))+[('sc_'+k,v) for k,v in zip(SC,b)]+[('cd_'+k,v) for k,v in zip(CD,c)]+[('cdt_'+k,v) for k,v in zip(CD,d)]
