    if 'stEnhance:' in src: continue
    lines=[]; 
    for i in range(0,len(pairs),6): lines.append('  '+', '.join(f"{k}: {json.dumps(v,ensure_ascii=False)}" for k,v in pairs[i:i+6])+',')
    i=src.rstrip().rfind('};'); src=src[:i]+'  // studio\n'+'\n'.join(lines)+'\n};\n'; open(D+l+'.js','w').write(src); print(l,len(pairs))
